def populate_test_result_revisions(apps, schema_editor):
    TestResult = apps.get_model("test_results", "TestResult")
    case_ids = (
        TestResult.objects
        .order_by()
        .values_list("case_id", flat=True)
        .distinct()
    )

    for case_id in case_ids.iterator():
        previous = None
        results = (
            TestResult.objects
            .filter(case_id=case_id)
            .order_by("performed_at", "created_at", "id")
        )
        for revision_number, result in enumerate(results.iterator(), start=1):
            update_fields = ["revision_number"]
            result.revision_number = revision_number
            if result.status == "CORRECTED" and result.supersedes_id is None:
                result.supersedes_id = previous
                update_fields.append("supersedes_id")
            result.save(update_fields=update_fields)
            previous = result.id


